SET NAMES utf8mb4;
SET SESSION sql_mode = "";

-- ---------- ۱) جدول و ستون‌ها ----------
-- اگر جدول seo_terms از قبل وجود دارد، این دستور رد می‌شود و
-- دو ALTER بعدی ستون‌های تازه را اضافه می‌کنند.

CREATE TABLE IF NOT EXISTS `seo_terms` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `heading` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `intro` text COLLATE utf8mb4_unicode_ci,
  `body` text COLLATE utf8mb4_unicode_ci,
  `faq` text COLLATE utf8mb4_unicode_ci,
  `seo_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `focus_keyword` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `robots_index` tinyint(1) NOT NULL DEFAULT '1',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `generated` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `seo_terms_type_slug_unique` (`type`,`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- MySQL دستور «ADD COLUMN IF NOT EXISTS» ندارد و ALTERِ ساده روی جدولی که
-- ستون را دارد خطای 1060 می‌دهد و اجرای کل فایل را متوقف می‌کند. پس اول
-- وجود ستون بررسی و بعد در صورت نیاز اضافه می‌شود؛ این شکل هم در
-- phpMyAdmin کار می‌کند و هم در خط فرمان، و چند بار اجرا کردنش بی‌خطر است.

SET @col := (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'seo_terms' AND COLUMN_NAME = 'faq');
SET @sql := IF(@col = 0, 'ALTER TABLE `seo_terms` ADD COLUMN `faq` TEXT NULL AFTER `body`', 'DO 0');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @col := (SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'seo_terms' AND COLUMN_NAME = 'generated');
SET @sql := IF(@col = 0, 'ALTER TABLE `seo_terms` ADD COLUMN `generated` TINYINT(1) NOT NULL DEFAULT 0 AFTER `is_active`', 'DO 0');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- ---------- ۲) محتوای صفحات فرود ----------
-- فقط رکوردهای تولیدشده پاک می‌شوند (generated = 1).
-- متنی که در پنل دستی نوشته شده باشد generated = 0 دارد و دست‌نخورده می‌ماند.
DELETE FROM `seo_terms` WHERE `generated` = 1;

