-- ---------- ۳) ثبت مهاجرت ----------
-- تا `php artisan migrate` بعدی دوباره همین مهاجرت را اجرا نکند.
SELECT '2026_08_19_000000_add_faq_to_seo_terms', 20
WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE `migration` = '2026_08_19_000000_add_faq_to_seo_terms');

